for (const [name, asset, image, ingredients, energy, health, buff, duration, source, price] of verifiedCooking) {
  const existing = entries.find(entry => entry.dataset === "cooking" && entry.name === name);
  const attributes = {
    ...existing?.attributes,
    ingredients, energy, health, buff, duration, source, sellPrice: price + "金",
    "资料来源": "https://stardewvalleywiki.com/" + asset,
    "数值说明": "普通品质、未使用齐氏调味料；持续时间不是游戏内时钟分钟。",
    "获取方式": "先取得配方：" + source + "。解锁厨房后，准备所列全部原料再制作。",
    "主要用途": "每份恢复" + energy + "点体力、" + health + "点生命；增益：" + buff + "；持续时间：" + duration + "。",
    "新手建议": "本配方每份需要：" + ingredients + "。制作前核对库存，避免消耗尚需献祭或送礼的材料。",
    "关联规划": "普通品质售价为" + price + "金；这是料理售价，不代表扣除全部原料成本后的利润。可结合种植与钓鱼安排备料。",
    links: existing?.attributes.links || ["/wiki/cooking", "/tools/crop-profit", "/tools/fish"]
  };
  if (existing) {
    existing.attributes = attributes;
    existing.summary = name + "的配方来源、原料数量、恢复值和增益时长。";
  } else {
    entries.push({ dataset: "cooking", name, image: "/assets/game/" + image,
      summary: name + "的配方来源、原料数量、恢复值和增益时长。", attributes });
  }
}

