for (const [name, slug, english, stats, reroll, restriction, note] of trinketAdditions) {
  const acquisition = slug === "magic-hair-gel"
    ? "领取战斗精通后，在沙漠节亚历克斯摆摊时用100枚卡利科三花蛋购买；必须等到对应摊位出现。"
    : "领取战斗精通后，可通过击杀怪物、破坏矿井等区域箱桶或骷髅洞穴宝箱随机获得；不是保证掉落。";
  entries.push({
    dataset: "items", slug, name, image: `/assets/game/${english}.png`,
    summary: `${name}是1.6版本加入的饰品。${stats}${restriction}`,
    attributes: {
      type: "饰品", source: acquisition, sellPrice: "1000金（探险家公会）",
      属性: stats, 装备条件: "五项技能达到10级后积累精通经验，领取战斗精通以解锁饰品栏；仅达到战斗10级不够。",
      重铸: reroll, 使用限制: restriction, 获取方式: acquisition,
      主要用途: `${stats}应装入饰品栏才会生效，放在背包里不会提供对应能力。`,
      新手建议: note, 关联规划: "先领取战斗精通，再依据下矿、刷掉落或击杀任务选择饰品；重铸前预留机器和工具所需铱锭。",
      资料来源: `https://stardewvalleywiki.com/${english}`,
      links: ["/wiki/skills", "/wiki/locations/adventurers-guild", "/wiki/items"]
    }
  });
}

