for (const [slug, name, icon, price, effect, acquisition, recipe, yieldText, restriction, type, sourceUrl] of fishingItemAdditions) {
  const compatibility = type === "鱼饵"
    ? "玻璃纤维鱼竿、铱金鱼竿和高级铱金鱼竿可用；训练用鱼竿和竹鱼竿不能使用鱼饵。"
    : "铱金鱼竿可装1个、高级铱金鱼竿可装2个；玻璃纤维鱼竿不能使用钓具。";
  entries.push({
    dataset: "items", slug, name, image: `/assets/game/${icon}.png`,
    summary: `${name}属于${type}。${effect}。${restriction}`,
    attributes: {
      type, source: acquisition, sellPrice: typeof price === "number" ? `${price}金` : price,
      属性: effect, 获取方式: acquisition, 制作配方: recipe, 制作产量: yieldText,
      适用装备: compatibility, 使用限制: restriction,
      主要用途: `${effect}。${compatibility}`,
      新手建议: `先确认目标鱼的地点和出现条件，再选择${name}；不要把咬钩速度、钓鱼条长度与品质效果混为一谈。`,
      关联规划: type === "钓具"
        ? "钓具通常经20次鱼咬钩耗尽；钓垃圾等非鱼物品不消耗耐久，已使用钓具的回售价可能降低，远行前准备备用件。"
        : "出发前检查鱼饵库存并选对鱼竿；消耗品与可反复使用一段时间的钓具分别准备，不把制作一批的材料误算成单个材料。",
      资料来源: sourceUrl, links: ["/tools/fish", "/wiki/fish", "/wiki/items"]
    }
  });
}

