for (const [slug, name, originalName, weaponType, level, damage, critical, bonuses, acquisition, purchase, sell, sourceUrl] of weaponAdditions) {
  entries.push({
    dataset: "items", slug, name, image: `/assets/game/Weapon_${slug}.png`,
    summary: `${name}属于${weaponType}，基础伤害${damage}。${acquisition}`,
    attributes: {
      type: "武器", 原名: originalName, 武器类型: weaponType, 等级: level,
      基础伤害: damage, 基础暴击概率: critical, 固定属性: bonuses,
      source: acquisition, 获取方式: acquisition, 购买价格: purchase, 基础售价: sell,
      主要用途: `用于战斗的${weaponType}。面板伤害和固定属性用于比较基础装备；实际伤害还会受到角色、敌人和强化状态影响。`,
      使用限制: weaponType === "弹弓" ? "弹弓需要装入可用弹药后射击，伤害随弹药变化；不能把其他武器的伤害区间套用到弹弓，也不能出售弹弓。" : "这里记录未锻造的基础数值，不代表每次命中伤害。购买、随机宝箱和锻造是不同获取方式；有随机矿井宝箱标注的奖励不属于默认宝箱配置。",
      新手建议: "先按自己能够到达的区域选择装备，再比较伤害、速度和防御。宝箱或怪物掉落并不保证一次取得，不应为未解锁装备预先花费预算。",
      关联规划: "保留正在使用的武器再出售替换下来的装备；计划无限系列时，先取得对应银河武器，并准备银河之魂和火山晶石。",
      资料来源: sourceUrl, links: ["/wiki/items", "/wiki/locations"]
    }
  });
}

