for (const [slug, name, gameId, kind, rotations, acquisition, effect, source, image, capacity] of furnitureAdditions) {
  entries.push({ dataset: "items", slug, name, image, summary: `${name}：${effect}`,
    attributes: { type: "家具", 家具类型: kind, 游戏物品编号: gameId, 旋转方向数: rotations,
      获取方式: acquisition, source: acquisition, 主要用途: effect, 出售限制: "不可出售，也不能赠送村民",
      新手建议: gameId === "(F)CCFishTank" ? "完成鱼缸收集包后到社区中心使用固定鱼缸；不能搬回农舍，也不能通过拾取重放改变装饰布局。" : "先检查放置位置的有效提示，并预留床边、门口和常用行走路线；不要把装饰家具当成生产机器。",
      关联规划: gameId === "(F)CCFishTank" ? "按底栖和游泳两类容量规划陈列，不要将修复场景设施误当作购买家具或建设鱼塘。" : `根据房间用途选择${kind}，再按获取途径安排预算或剧情条件；目录中的免费取用不代表可以出售套利。`,
      ...(capacity ? { 展示容量: capacity } : {}),
      资料来源: source, links: ["/wiki/items", "/wiki/locations"] }
  });
}

