for (const [id, name, slug, item, recipe, effect, note] of masteryAdditions) {
  entries.push({ dataset: "skills", name, slug, image: `/assets/game/Mastery_${id}.png`,
    summary: `${name}：五项技能满级后的独立精通奖励，包含${recipe}，需主动领取。`,
    attributes: { type: "技能精通", 解锁条件: "五项技能全部达到10级后，才能进入精通山洞并开始积累精通经验。",
      获取方式: "全技能10级后积累精通经验，到煤矿森林精通山洞对应柱子主动领取；不是技能升到10级就自动领取全部奖励。",
      经验换算: "耕种经验按50%计入，其他四项技能按100%计入；五项全部满级之前不积累精通经验。",
      累计经验门槛: "10000 / 25000 / 45000 / 70000 / 100000",
      领取规则: "五项精通可按任意顺序领取；新增一级所需经验依次为10000、15000、20000、25000、30000。未领取也能继续积累。",
      实物奖励: item, 配方奖励: recipe, 解锁效果: effect, 主要用途: effect, 注意事项: note, 新手建议: note,
      关联规划: "先根据当前瓶颈选择奖励；实物、制作配方和被动解锁分别生效，领取配方后仍需筹备材料。",
      资料来源: "https://stardewvalleywiki.com/Mastery_Cave", links: ["/wiki/skills", "/guides/mastery-system-guide-1-6"] }
  });
}

