for (const [name, slug, image, location, floors, variant, stats, tip, condition, discrepancy, sourceUrl] of monsterAdditions) {
  entries.push({ dataset: "items", name, slug, image,
    summary: `${name}：出现在${location}的${variant}，需按对应楼层与战斗机制辨认。`,
    attributes: { type: "怪物", 出现地点: location, 出现楼层: floors, 形态: variant, ...stats,
      获取方式: `在${location}寻找，楼层说明：${floors}。这是敌对生物资料，不是商店可以买来使用的物品。`,
      主要用途: "辨认矿洞和农场敌人、规划战斗准备与探索路线；是否计入公会目标需按对应怪物类别核对。",
      应对方法: tip, 条件说明: condition, 数值复核: discrepancy, 新手建议: tip,
      关联规划: "普通怪物、危险变体与同名材料不能混用；准备武器、食物和逃生物品后，再进入对应探索区域。",
      资料来源: sourceUrl, links: ["/wiki/items", "/guides/mines-floor-120-resource-monster-route"] }
  });
}

